import csv, math
from decimal import Decimal, ROUND_HALF_UP, ROUND_HALF_EVEN
rows=list(csv.DictReader(open('fixtures/transactions.csv')))
rates={('USD','EUR'):0.9228,('EUR','USD'):1.0837}
def bal(conv):
    b={}
    for r in rows:
        amt=int(r['amount_cents']); cur=r['currency']
        for code,sign in ((r['debit'],1),(r['credit'],-1)):
            acc_cur = 'EUR' if code=='4471' else 'USD'
            rate = 1.0 if cur==acc_cur else rates[(cur,acc_cur)]
            b[code]=b.get(code,0)+sign*conv(amt,rate)
    return b
import collections
cnt=collections.Counter((r['currency'], r['debit']=='4471' or r['credit']=='4471') for r in rows)
print(cnt)
def hu(c,r): return int(Decimal(c)*Decimal(str(r)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)) if False else int((Decimal(c)*Decimal(str(r))).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
def he(c,r): return int((Decimal(c)*Decimal(str(r))).quantize(Decimal('1'), rounding=ROUND_HALF_EVEN))
def fl(c,r): return math.floor(c*r)
ctrl={r['account']:int(r['balance_cents']) for r in csv.DictReader(open('fixtures/controls.csv'))}
for name,f in [('trunc',lambda c,r:int(c*r)),('half_up',hu),('half_even',he),('floor',fl),('round',lambda c,r:round(c*r))]:
    b=bal(f)
    print(name, {k:b[k]-ctrl[k] for k in ctrl})
